const CACHE='os-facil-shell-v4';
const SHELL=['/demo.css','/demo.js','/','/app.js','/polish.css','/experience.js','/logo.svg','/icon-192.png','/icon-512.png','/icon-maskable.png','/manifest.webmanifest'];
self.addEventListener('install',event=>{event.waitUntil((async()=>{const responses=await Promise.all(SHELL.map(async url=>{const response=await fetch(new Request(url,{cache:'reload',credentials:'same-origin'}));if(!response.ok||response.redirected||response.type!=='basic')throw new Error('App shell unavailable');return [url,response]}));const cache=await caches.open(CACHE);await Promise.all(responses.map(([url,response])=>cache.put(url,response)));await self.skipWaiting()})())});
self.addEventListener('activate',event=>{event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('os-facil-shell-')&&key!==CACHE)await caches.delete(key);await self.clients.claim()})())});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin)return;const navigation=event.request.mode==='navigate';if(navigation&&url.pathname!=='/'&&url.pathname!=='/index.html')return;if(!navigation&&!SHELL.includes(url.pathname))return;const key=navigation?'/':url.pathname;event.respondWith((async()=>{try{const response=await fetch(event.request);if(response.status>=500){const cached=await caches.match(key);if(cached)return cached}if(response.ok&&!response.redirected&&response.type==='basic'){const cache=await caches.open(CACHE);await cache.put(key,response.clone())}return response}catch{return await caches.match(key)||Response.error()}})())});
